import { CloverDexType, RouterType } from '../consts';
import { IRouterContext } from './RouterContext';
import {
  Account,
  Address,
  Blockhash,
  FullySignedTransaction,
  Instruction,
  Rpc,
  Signature,
  SolanaRpcApi,
  Transaction,
} from '@solana/kit';
import BN from 'bn.js';
import { TOKEN_PROGRAM_ADDRESS } from '@solana-program/token';
import { AddressLookupTable } from '@solana-program/address-lookup-table';

export interface Router {
  readonly routerType: RouterType;
  readonly connection: Rpc<SolanaRpcApi>;

  route: (params: RouteParams, ctx: IRouterContext) => Promise<RouteOutput[] | undefined>;
  quote: (params: QuoteParams) => Promise<RouteOutput[] | undefined>;
}

type RouteOutputBase = {
  ixsRouter?: Instruction[];
  amountsExactIn: AmountExactIn;
  amountsExactOut: AmountExactOut;
  swapType: SwapType;
  responseTimeGetQuoteMs: number;
  responseTimeSwapIxsMs: number;
  routerType: RouterType;
  priceImpactBps?: number;
  simulatedPriceImpactBps?: number;
  guaranteedPriceImpactBps?: number;
  expiryTime: number;
  perReferenceId?: string;
  birdeyeTokenInPriceInSol?: number;
  birdeyeTokenOutPriceInSol?: number;
  inputMintProgramOwner?: Address;
  outputMintProgramOwner?: Address;
  inputTokenDecimals?: number;
  outputTokenDecimals?: number;
  jupRequestId?: string;
  cloverDexType?: CloverDexType;
  skipLimoLogsForRoute?: boolean; // Indicates if limo logs should be skipped for this route (based on simulation success)
  /**
   * Optional simulation result object that contains the success status, error message, and logs
   */
  simulationResult?: RouteSimulationResult;
};

type WithTransaction = {
  transaction: Transaction;
  lookupTableAccounts: Account<AddressLookupTable>[];
};

type WithoutTransaction = {
  transaction?: never;
  lookupTableAccounts?: Account<AddressLookupTable>[];
};

export type RouteOutput = RouteOutputBase & (WithTransaction | WithoutTransaction);

export type AmountExactIn = {
  amountIn: BN;
  amountOutGuaranteed: BN;
  amountOut: BN;
  amountOutSimulated?: BN;
};

export type AmountExactOut = {
  amountOut: BN;
  amountInGuaranteed: BN;
  amountIn: BN;
  amountInSimulated?: BN;
};

export type SwapType = 'exactIn' | 'exactOut';

export type RouteSimulationResult = {
  /**
   * Indicates if the simulation was successful
   */
  success: boolean;
  /**
   * Cause of the failure if `success` is false
   */
  errorReason?: SimulationErrorReason;
  /**
   * Logs generated during the simulation
   */
  logs?: string[];
  /**
   * Timestamp of the simulation
   */
  simulationTimestamp?: number;
};

export enum SimulationErrorReason {
  Unknown = 'UNKNOWN',
  SlippageExceeded = 'SLIPPAGE_EXCEEDED',
  TooManyAccountLocks = 'TOO_MANY_ACCOUNT_LOCKS',
}

export type RouteParams = {
  tokenIn: Address;
  tokenOut: Address;
  amount: BN;
  swapType: SwapType;
  executor: Address;
  maxSlippageBps: number;
  referrerPda?: Address;
  includeSetupIxs?: boolean;
  wrapAndUnwrapSol?: boolean;
  routerTypes?: RouterType[];
  includeLimoLogs?: boolean;
  includeRfq?: boolean;
  timeoutMs?: number;
  atLeastOneNoMoreThanTimeoutMS?: number;
  withSimulation?: boolean;
  /**
   * Optional flag to filter out failed simulations from the results
   * Only applicable if `withSimulation` is true
   */
  filterFailedSimulations?: boolean;
  destinationTokenAccount?: Address;
  preferredMaxAccounts?: number;
  requestPriceImpact?: boolean; // TODO: Implement functionality for this once passed in the FE
  perMinimumQuoteLifetimeSeconds?: number; // Minimum lifetime for per swap execution
  assertSwapBalances?: boolean;
  overrideAssertMaxInputAmountChange?: BN; // Optional override for assert max input amount change
  overrideAssertMinOutputAmountChange?: BN; // Optional override for assert min output amount change
  simulateWithMockInputAmount?: boolean; // Optional flag to simulate with a mock input amount
};

export type RouteOrQuoteParams = {
  tokenIn: Address;
  tokenOut: Address;
  amount: BN;
  swapType: SwapType;
  executor?: Address;
  maxSlippageBps: number;
  referrerPda?: Address;
  includeSetupIxs?: boolean;
  wrapAndUnwrapSol?: boolean;
  routerTypes?: RouterType[];
  includeLimoLogs?: boolean;
  includeRfq?: boolean;
  timeoutMs?: number;
  atLeastOneNoMoreThanTimeoutMS?: number;
  withSimulation?: boolean;
  filterFailedSimulations?: boolean;
  destinationTokenAccount?: Address;
  preferredMaxAccounts?: number;
  requestPriceImpact?: boolean; // TODO: Implement functionality for this once passed in the FE
  perMinimumQuoteLifetimeSeconds?: number; // Minimum lifetime for per swap execution
  assertSwapBalances?: boolean;
  overrideAssertMaxInputAmountChange?: BN; // Optional override for assert max input amount change
  overrideAssertMinOutputAmountChange?: BN; // Optional override for assert min output amount change
  simulateWithMockInputAmount?: boolean; // Optional flag to simulate with a mock input amount
};

// Utility types to ensure all optional parameters are properly handled
type RequiredParams = 'tokenIn' | 'tokenOut' | 'amount' | 'swapType' | 'maxSlippageBps';
type QuoteOnlyParams = 'executor'; // executor is optional/undefined for quotes only
type RouteOnlyParams =
  | 'referrerPda'
  | 'includeSetupIxs'
  | 'wrapAndUnwrapSol'
  | 'includeLimoLogs'
  | 'withSimulation'
  | 'destinationTokenAccount';

// Ensure RouteParams contains all parameters from RouteOrQuoteParams except those quote-specific
type _RouteParamsCheck = Required<Pick<RouteOrQuoteParams, RequiredParams>> &
  Required<Pick<RouteOrQuoteParams, 'executor'>> &
  Pick<RouteOrQuoteParams, Exclude<keyof RouteOrQuoteParams, RequiredParams | 'executor'>>;

// Ensure QuoteParams contains all shared parameters except route-only ones
type _QuoteParamsCheck = Required<Pick<RouteOrQuoteParams, RequiredParams>> &
  Pick<RouteOrQuoteParams, Exclude<keyof RouteOrQuoteParams, RequiredParams | RouteOnlyParams>>;

// Type assertions to ensure compatibility - these will cause TypeScript errors if the types diverge
const _routeParamsTypeCheck: _RouteParamsCheck = {} as RouteParams;
const _quoteParamsTypeCheck: _QuoteParamsCheck = {} as QuoteParams;

