export function getQuoteParamsKeys(): (keyof QuoteParams)[] {
  const keyMap: { [K in keyof QuoteParams]-?: K } = {
    tokenIn: 'tokenIn',
    tokenOut: 'tokenOut',
    amount: 'amount',
    swapType: 'swapType',
    maxSlippageBps: 'maxSlippageBps',
    routerTypes: 'routerTypes',
    includeRfq: 'includeRfq',
    timeoutMs: 'timeoutMs',
    atLeastOneNoMoreThanTimeoutMS: 'atLeastOneNoMoreThanTimeoutMS',
    preferredMaxAccounts: 'preferredMaxAccounts',
    requestPriceImpact: 'requestPriceImpact',
    executor: 'executor',
  };

  return Object.keys(keyMap) as (keyof QuoteParams)[];
}

